<form class="card max-w-3xl space-y-5 p-6" method="post" action="<?=url('contacts/save')?>"><?=csrf_field()?><input type="hidden" name="id" value="<?=e($contact['id'])?>"><div class="grid gap-4 sm:grid-cols-2"><label class="sm:col-span-2"><span class="label">Nome</span><input class="field" name="name" value="<?=e($contact['name'])?>" required></label><label><span class="label">CNPJ/CPF</span><input class="field" name="document" value="<?=e($contact['document'])?>"></label><label><span class="label">Tipo</span><select class="field" name="type"><?php foreach(['fornecedor'=>'Fornecedor','cliente'=>'Cliente','ambos'=>'Ambos'] as $v=>$l):?><option value="<?=$v?>" <?=$contact['type']===$v?'selected':''?>><?=$l?></option><?php endforeach;?></select></label><label><span class="label">Telefone</span><input class="field" name="phone" value="<?=e($contact['phone'])?>"></label><label><span class="label">E-mail</span><input class="field" type="email" name="email" value="<?=e($contact['email'])?>"></label><label class="sm:col-span-2"><span class="label">Observações</span><textarea class="field" name="notes" rows="4"><?=e($contact['notes'])?></textarea></label></div><div class="flex gap-3"><button class="btn btn-primary">Salvar</button><a class="btn btn-light" href="<?=url('contacts')?>">Cancelar</a></div></form>
